-- Project Sealed Hold Phase 3: provider evidence and leased scheduled operations.
CREATE TABLE `PrivateProviderHealthSnapshot` (`id` VARCHAR(191) NOT NULL, `kind` VARCHAR(64) NOT NULL, `provider` VARCHAR(191) NOT NULL, `state` VARCHAR(64) NOT NULL, `safeCode` VARCHAR(191) NOT NULL, `evidence` LONGTEXT NOT NULL, `checkedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `PrivateProviderHealthSnapshot_kind_checkedAt_idx` (`kind`,`checkedAt`));
CREATE TABLE `PrivateScheduledOperation` (`id` VARCHAR(191) NOT NULL, `kind` VARCHAR(64) NOT NULL, `scheduleKey` VARCHAR(191) NOT NULL, `state` VARCHAR(64) NOT NULL DEFAULT 'PENDING', `runAfter` DATETIME(3) NOT NULL, `leaseOwner` VARCHAR(191) NULL, `leaseUntil` DATETIME(3) NULL, `lastError` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `PrivateScheduledOperation_scheduleKey_key` (`scheduleKey`), KEY `PrivateScheduledOperation_state_runAfter_leaseUntil_idx` (`state`,`runAfter`,`leaseUntil`));
